examples:
只读遍历节点 22 的所有相邻节点：
auto iterBegin { graph.cbegin(22) };
auto iterEnd { graph.cend(22) };
if (iterBegin == directed_graph<int>::const_iterator_adjacent_nodes{}) {
    std::cout << "Value 22 not found." << std::endl;
} else {
    for (auto iter { iterBegin }; iter != iterEnd; ++iter) {
        std::cout << *iter << " ";
    }
}
